    let saveTimer = 0; const renderPreview = () => { const previewDefinition = guide ? { ...definition, steps: [guide.steps[stepIndex]] } : definition; return this.preview.render({ id: draft.experience.id, versionId: draft.version.id, kind: draft.experience.kind, widgetType: draft.experience.widgetType, priority: 0, definition: previewDefinition }, { onVisible: () => void 0, onDismiss: () => window.setTimeout(renderPreview, 0), onAction: () => void 0, onComplete: () => window.setTimeout(renderPreview, 0) }); }; const persist = async () => { status.textContent = "Saving…"; try { await bridge.save(definition); status.textContent = "Draft saved."; } catch { status.textContent = "Editor session expired or was revoked."; this.destroy(); } }; const save = () => { renderPreview(); clearTimeout(saveTimer); saveTimer = window.setTimeout(persist, 350); };
